def find_midpoint_closed_sets(n):
    midpoint_closed_sets = []
    for i in range(1, 1 << n):
        K = [j for j in range(n) if (i >> j) & 1]
        if len(K) < 3:
            continue

        is_closed = True
        for p in K:
            for q in K:
                # Find r such that 2r = p + q (mod n)
                # Since n is odd, 2 has an inverse modulo n.
                # 2r = p + q (mod n)  =>  r = (p+q) * inv(2, n) (mod n)
                # inv(2, n) = (n+1)/2
                r = ((p + q) * (n + 1) // 2) % n
                if r not in K:
                    is_closed = False
                    break
            if not is_closed:
                break

        if is_closed:
            midpoint_closed_sets.append(set(K))

    sizes = set(len(K) for K in midpoint_closed_sets)
    return sizes, midpoint_closed_sets

# Test for small odd n
for n in [3, 5, 7, 9, 11, 13, 15]:
    sizes, sets = find_midpoint_closed_sets(n)
    print(f"n={n}, sizes={sizes}")

