def find_midpoint_closed_sets_recursive(n):
    # A midpoint-closed set K must satisfy:
    # 1. For any p, q in K, (p+q)/2 is in K.
    # 2. |K| >= 3.

    # Let's try to build K starting from a small set.
    # If we have p, q in K, then (p+q)/2 must be in K.
    # If we have p, r in K, then (p+r)/2 must be in K.
    # This means if we have two elements, we can find more.
    # Let's start with any two elements {a, b} and find the closure.

    closed_sets = []
    for a in range(n):
        for b in range(a + 1, n):
            K = {a, b}
            while True:
                new_elements = set()
                for p in K:
                    for q in K:
                        r = ((p + q) * (n + 1) // 2) % n
                        if r not in K:
                            new_elements.add(r)
                if not new_elements:
                    break
                K.update(new_elements)
            if len(K) >= 3:
                closed_sets.append(K)

    sizes = set(len(K) for K in closed_sets)
    return sizes

