def find_all_midpoint_closed_sets(n):
    # K is midpoint-closed if for all p, q in K, (p+q)/2 mod n is in K.
    # Since n is odd, r = (p+q)*(n+1)//2 mod n is the unique midpoint.

    # We can use a BFS-like approach to find all midpoint-closed sets.
    # A midpoint-closed set is uniquely determined by any two of its elements?
    # No, that's not true. But it is determined by any two elements that are
    # "adjacent" in some sense.

    midpoint_closed_sets = []
    # Try all pairs (a, b) and find their closure.
    for a in range(n):
        for b in range(a + 1, n):
            K = {a, b}
            while True:
                new_elements = set()
                for p in K:
                    for q in K:
                        r = ((p + q) * (n + 1) // 2) % n
                        if r not in K:
                            new_elements.add(r)
                if not new_elements:
                    break
                K.update(new_elements)
            if len(K) >= 3:
                midpoint_closed_sets.append(K)

    # Also need to consider sets that are not generated by 2 elements?
    # Actually, any midpoint-closed set K with |K| > 1 must have at least 
    # two elements a, b. The closure of {a, b} is the smallest midpoint-closed 
    # set containing a and b.
    # If K is midpoint-closed, then it must be the closure of some pair {a, b} 
    # in it (unless |K|=1).

    # Let's check n=21.
    sizes = set(len(K) for K in midpoint_closed_sets)
    return sizes

