def solve_small_n_v2(n):
    inv2 = pow(2, -1, n)
    # Let's check if all cosets of all subgroups work.
    # Subgroups of Z_n are of the form d*Z_n where d|n.
    # The size of such a subgroup is n/d.
    # There are d such subgroups (0, d, 2d, ..., (n/d-1)d). No, there are d cosets.
    # The number of subgroups of size n/d is one? No, for each divisor k of n,
    # there is a unique subgroup of order k.
    # Let k be a divisor of n. The subgroup H of order k is {0, n/k, 2n/k, ..., (k-1)n/k}.
    # Let d = n/k. Then H = {0, d, 2d, ..., (k-1)d}.
    # The cosets are H + x = {x, x+d, x+2d, ..., x+(k-1)d}.

    possible_sizes = set()
    for k in range(1, n + 1):
        if n % k == 0:
            # This k is a potential size of a subgroup.
            d = n // k
            # Check all cosets of the subgroup H = {0, d, 2d, ..., (k-1)d}
            # Actually, all cosets of H have the same size k.
            # We just need to check if these cosets are midpoint-closed.
            # We already proved they are, but let's check one.
            K = [x + i * d for i in range(k)]
            is_closed = True
            for p in K:
                for q in K:
                    if (p + q) * inv2 % n not in K:
                        is_closed = False
                        break
                if not is_closed:
                    break
            if is_closed:
                possible_sizes.add(k)
    return sorted(list(possible_sizes))

for n in [5, 7, 9, 11, 13]:
    print(f"n={n}: {solve_small_n_v2(n)}")

