def solve_small_n_v3(n):
    inv2 = pow(2, -1, n)
    possible_sizes = set()
    for i in range(1 << n):
        K = [j for j in range(n) if (i >> j) & 1]
        if not K: continue
        is_closed = True
        for p in K:
            for q in K:
                if (p + q) * inv2 % n not in K:
                    is_closed = False
                    break
            if not is_closed:
                break
        if is_closed:
            possible_sizes.add(len(K))
    return sorted(list(possible_sizes))

